# ===== 00-core.sh =====
# shellcheck shell=bash
# shellcheck disable=SC2034  # globals are used by other lib/ modules
# =============================================================================
#  ayneh — Iranian repository mirror scanner & configurator
# -----------------------------------------------------------------------------
#  Scans npm / PyPI / Docker / Linux package repos (apt, dnf/yum, pacman, apk)
#  for HTTP reachability, and when an upstream is unreachable lets you switch
#  to an Iranian mirror (ArvanCloud, Liara, and more) from a terminal menu.
#
#  License: MIT
# =============================================================================
#
#  This file is part of the modular source tree. The single-file script that
#  users download with `curl ... | bash` is generated by build.sh from the
#  files in lib/ — never edit dist/ayneh.sh by hand.
# =============================================================================

set -uo pipefail

# We use bash 4 features (${var,,} lowercasing, associative arrays). Every
# mainstream Linux ships bash >= 4; give a clear message instead of a cryptic
# parse error on an ancient bash.
if (( BASH_VERSINFO[0] < 4 )); then
    echo "ayneh: requires bash 4 or newer (you have ${BASH_VERSION})." >&2
    exit 1
fi

AYNEH_VERSION="2.0.0"
PROG="ayneh"
AYNEH_REPO="${AYNEH_REPO:-ihamedm/ayneh}"
AYNEH_BRANCH="${AYNEH_BRANCH:-main}"

# Where backups are stored. User-scope backups under HOME, system-scope under
# /var/backups.
USER_BACKUP_DIR="${HOME}/.ayneh-backup"
# Legacy location used by the 1.x script; still read so old backups work.
LEGACY_USER_BACKUP_DIR="${HOME}/.mirrors-backup"
SYS_BACKUP_DIR="/var/backups/ayneh"
LEGACY_SYS_BACKUP_DIR="/var/backups/mirrors"

# Probe timeouts (seconds). Override for slow links, e.g.
#   AYNEH_CONNECT_TIMEOUT=10 AYNEH_MAX_TIME=25 ayneh --scan
AYNEH_CONNECT_TIMEOUT="${AYNEH_CONNECT_TIMEOUT:-6}"
AYNEH_MAX_TIME="${AYNEH_MAX_TIME:-12}"

# Number of failed probes in the current scan (used for the summary line).
AYNEH_PROBE_FAILURES="${AYNEH_PROBE_FAILURES:-0}"

# -----------------------------------------------------------------------------
# Terminal colors (auto-disabled when not a tty, when NO_COLOR is set, or on a
# dumb terminal). Checked once.
# -----------------------------------------------------------------------------
if [[ -t 1 && "${TERM:-}" != "dumb" && -z "${NO_COLOR:-}" ]]; then
    C_RED=$'\033[31m';    C_GREEN=$'\033[32m';  C_YELLOW=$'\033[33m'
    C_BLUE=$'\033[34m';   C_MAGENTA=$'\033[35m'; C_CYAN=$'\033[36m'
    C_BOLD=$'\033[1m';    C_DIM=$'\033[2m';      C_OFF=$'\033[0m'
else
    C_RED=""; C_GREEN=""; C_YELLOW=""; C_BLUE=""; C_MAGENTA=""; C_CYAN=""
    C_BOLD=""; C_DIM=""; C_OFF=""
fi

# -----------------------------------------------------------------------------
# Logging helpers
# -----------------------------------------------------------------------------
info()  { printf '%s\n' "${C_CYAN}[i]${C_OFF} $*"; }
ok()    { printf '%s\n' "${C_GREEN}[+]${C_OFF} $*"; }
warn()  { printf '%s\n' "${C_YELLOW}[!]${C_OFF} $*"; }
err()   { printf '%s\n' "${C_RED}[x]${C_OFF} $*" >&2; }
die()   { err "$*"; exit 1; }
hdr()   { printf '\n%s\n' "${C_BOLD}${C_BLUE}=== $* ===${C_OFF}"; }

# -----------------------------------------------------------------------------
# Prompting
# -----------------------------------------------------------------------------

# Read one line from the controlling terminal. This is what makes the menu
# work even when the script was piped in via `curl ... | bash` (where stdin
# is the script body, not the keyboard).
ask() {
    local _var="$1"; shift
    printf '%s' "$*"
    local _rc
    # Open /dev/tty once instead of testing it with -r: in containers/CI it
    # can exist as a character device but still have no controlling terminal,
    # and the failed redirection itself would leak an error to stderr.
    if { exec 3</dev/tty; } 2>/dev/null; then
        # shellcheck disable=SC2229  # reading into a dynamically named variable
        IFS= read -r "$_var" <&3 2>/dev/null; _rc=$?
        exec 3<&-
    else
        # shellcheck disable=SC2229
        IFS= read -r "$_var" 2>/dev/null; _rc=$?
    fi
    # EOF (read returns non-zero): default to empty so callers never see an
    # unset value under `set -u`, and propagate the non-zero status so menu
    # loops can break instead of spinning forever on a closed stdin.
    [[ $_rc -ne 0 ]] && eval "$_var=''"
    return $_rc
}

confirm() {
    local prompt="$1" default="${2:-y}" yn
    if [[ "$default" =~ ^[Yy] ]]; then
        ask yn "${prompt} [Y/n] "
    else
        ask yn "${prompt} [y/N] "
    fi
    yn="${yn:-$default}"
    [[ "$yn" =~ ^[Yy] ]]
}

pause() {
    local _d
    ask _d "${C_DIM}— press Enter to continue —${C_OFF}"
}

# -----------------------------------------------------------------------------
# Privileges
# -----------------------------------------------------------------------------
running_as_root() { [[ "${EUID:-$(id -u)}" -eq 0 ]]; }

# Run a command with sudo if we are not root, otherwise directly.
# Uses non-interactive sudo only (cached creds / NOPASSWD) so it never hangs
# or spews password errors in non-tty contexts. Callers that MUST have root
# should call require_root() first.
maybe_sudo() {
    if running_as_root; then "$@"; return $?; fi
    sudo -n "$@" 2>/dev/null; return $?
}

# Make sure we can use sudo, asking for a password on the controlling tty when
# needed (cached/NOPASSWD sudo returns immediately). This keeps the tool usable
# on a fresh server without forcing the user to prefix every command with sudo,
# while still working when the script is piped through `curl | bash`.
ensure_sudo() {
    running_as_root && return 0
    sudo -n true 2>/dev/null && return 0
    if [[ -r /dev/tty ]]; then
        printf '%s\n' "${C_DIM}Root privileges are needed; sudo may ask for your password.${C_OFF}" >/dev/tty
        if sudo -v; then
            return 0
        fi
    fi
    return 1
}

# Guard for system-scope applies: fail fast with a clear message instead of
# leaking sudo password errors mid-operation.
require_root() {
    local svc="$1" name="$2"
    if ensure_sudo; then return 0; fi
    err "This modifies system files and requires root (or passwordless sudo)."
    err "Re-run as:  sudo ayneh --apply ${svc} \"${name}\""
    return 1
}

# Real invoking user's HOME (when running under sudo).
real_home() {
    if [[ -n "${SUDO_USER:-}" ]]; then
        local h
        h="$(getent passwd "$SUDO_USER" 2>/dev/null | cut -d: -f6 || true)"
        [[ -n "$h" ]] && { printf '%s\n' "$h"; return 0; }
    fi
    printf '%s\n' "${HOME:-/root}"
}

have() { command -v "$1" >/dev/null 2>&1; }

# -----------------------------------------------------------------------------
# Scratch space (cleaned up on exit)
# -----------------------------------------------------------------------------
AYNEH_TMPDIR="${AYNEH_TMPDIR:-}"

ensure_tmpdir() {
    [[ -n "$AYNEH_TMPDIR" && -d "$AYNEH_TMPDIR" ]] && return 0
    AYNEH_TMPDIR="$(mktemp -d "${TMPDIR:-/tmp}/ayneh.XXXXXX")" || die "Could not create a temporary directory."
}

cleanup() {
    [[ -n "$AYNEH_TMPDIR" && -d "$AYNEH_TMPDIR" ]] && rm -rf "$AYNEH_TMPDIR"
    return 0
}

trap cleanup EXIT
trap 'cleanup; exit 130' INT
trap 'cleanup; exit 143' TERM

# ===== 10-os.sh =====
# shellcheck shell=bash
# =============================================================================
# OS / package-manager detection and service detectors
# =============================================================================
DISTRO_ID="unknown"; DISTRO_FAMILY="unknown"; DISTRO_CODENAME=""
DISTRO_VERSION=""; DISTRO_ARCH=""; PKGMGR="none"

detect_os() {
    DISTRO_ARCH="$(uname -m 2>/dev/null || echo x86_64)"
    [[ -z "$DISTRO_ARCH" ]] && DISTRO_ARCH="x86_64"

    local osr=""
    [[ -f /etc/os-release ]] && osr=/etc/os-release
    [[ -z "$osr" && -f /usr/lib/os-release ]] && osr=/usr/lib/os-release

    if [[ -n "$osr" ]]; then
        # shellcheck disable=SC1090
        . "$osr" 2>/dev/null || true
        DISTRO_ID="${ID:-unknown}"
        DISTRO_ID="${DISTRO_ID,,}"                # lowercase
        DISTRO_VERSION="${VERSION_ID:-}"
        DISTRO_CODENAME="${VERSION_CODENAME:-}"
        # ID_LIKE gives the family for derivatives (e.g. Ubuntu's ID_LIKE=debian)
        local like="${ID_LIKE:-}"
        like="${like,,}"
        case "$DISTRO_ID|$like" in
            *debian*|*ubuntu*|*linuxmint*|*kali*|*raspbian*|*mx*|*devuan*) DISTRO_FAMILY="debian" ;;
            *rhel*|*fedora*|*centos*|*rocky*|*almalinux*|*oraclelinux*|*amazon*|*amzn*|*scientific*|*clearos*|*kylin*|*anolis*|*eurolinux*) DISTRO_FAMILY="rhel" ;;
            *arch*|*manjaro*|*garuda*|*endeavouros*|*cachyos*|*arcolinux*|*artix*) DISTRO_FAMILY="arch" ;;
            *alpine*) DISTRO_FAMILY="alpine" ;;
            *opensuse*|*suse*|*sles*|*tumbleweed*|*leap*) DISTRO_FAMILY="suse" ;;
            *void*) DISTRO_FAMILY="void" ;;
            *gentoo*) DISTRO_FAMILY="gentoo" ;;
            *nixos*) DISTRO_FAMILY="nixos" ;;
            *slackware*) DISTRO_FAMILY="slackware" ;;
            *) DISTRO_FAMILY="${DISTRO_ID}";;
        esac
    fi

    # Codename fallbacks for distros that don't set VERSION_CODENAME
    if [[ -z "$DISTRO_CODENAME" ]]; then
        case "$DISTRO_FAMILY" in
            debian)
                if have lsb_release; then DISTRO_CODENAME="$(lsb_release -cs 2>/dev/null)"
                elif [[ -f /etc/debian_version ]]; then DISTRO_CODENAME="$(cut -d/ -f1 /etc/debian_version 2>/dev/null)"
                fi ;;
            arch) DISTRO_CODENAME="rolling" ;;
            alpine) DISTRO_CODENAME="$(alpine_branch)" ;;
        esac
    fi

    # Detect available package manager(s)
    PKGMGR="none"
    if have apt-get || have apt;        then PKGMGR="apt"
    elif have dnf;                      then PKGMGR="dnf"
    elif have yum;                      then PKGMGR="yum"
    elif have pacman;                   then PKGMGR="pacman"
    elif have apk;                      then PKGMGR="apk"
    elif have zypper;                   then PKGMGR="zypper"
    elif have xbps-install;             then PKGMGR="xbps"
    elif have emerge;                   then PKGMGR="portage"
    fi
}

os_summary() {
    printf '%s: %s %s (%s)\n' "OS" "${DISTRO_ID}" "${DISTRO_VERSION}" "${DISTRO_ARCH}"
    printf '%s: %s\n' "Family" "$DISTRO_FAMILY"
    printf '%s: %s\n' "Codename" "${DISTRO_CODENAME:-n/a}"
    printf '%s: %s\n' "Package manager" "$PKGMGR"
}

# Alpine release branch ("v3.20") from VERSION_ID ("3.20.3"). "edge" when the
# version is unknown (edge images, custom builds).
alpine_branch() {
    local v="${DISTRO_VERSION:-}"
    if [[ -z "$v" || "$v" == "edge" ]]; then
        printf '%s\n' "edge"
        return 0
    fi
    printf 'v%s\n' "$(printf '%s' "$v" | awk -F. '{print $1"."$2}')"
}

# -----------------------------------------------------------------------------
# Service detectors (is the toolchain present?)
# -----------------------------------------------------------------------------
has_npm()    { have npm; }
has_pip()    { have pip || have pip3; }
has_docker() { have docker || [[ -d /etc/docker ]]; }
has_apt()    { [[ "$DISTRO_FAMILY" == "debian" ]] && (have apt-get || have apt); }
has_yum()    { [[ "$DISTRO_FAMILY" == "rhel"  ]] && (have dnf || have yum); }
has_pacman() { [[ "$DISTRO_FAMILY" == "arch"  ]] && have pacman; }
has_apk()    { [[ "$DISTRO_FAMILY" == "alpine" ]] && have apk; }

pip_cmd() { have pip3 && echo pip3 || echo pip; }

# ===== 20-http.sh =====
# shellcheck shell=bash
# =============================================================================
# HTTP probe helpers
# =============================================================================

# The tool is written around curl; fail early with an actionable message.
require_curl() {
    have curl || die "curl is required but was not found in PATH. Install it (e.g. apt install curl) and retry."
}

# Print HTTP status code for a URL ("000" on failure). Fast and reliable.
# --max-filesize aborts the body download the instant it starts (we only need
# the status line), so probes stay quick even for multi-MB responses. We do NOT
# add a "|| echo 000" fallback: %{http_code} already prints "000" when curl
# never reached the server, and appending "000" after a real code on curl's
# non-zero exit (63=max-filesize, 28=timeout) would corrupt the value.
http_code() {
    local url="$1"
    curl -s -o /dev/null -w '%{http_code}' \
         --max-filesize 1024 \
         --connect-timeout "$AYNEH_CONNECT_TIMEOUT" \
         --max-time "$AYNEH_MAX_TIME" \
         -L "$url" 2>/dev/null
}

# Probe a URL and print a human-readable status line.
# $1=label  $2=url  $3=comma-separated "good" codes (default 200)
probe_url() {
    local label="$1" url="$2" good="${3:-200}" code
    code="$(http_code "$url")"
    local status color
    if [[ ",$good," == *",$code,"* ]]; then
        status="OK"; color="$C_GREEN"
    elif [[ "$code" == "000" ]]; then
        status="UNREACHABLE"; color="$C_RED"
    else
        status="HTTP $code"; color="$C_YELLOW"
    fi
    printf '  %s%-12s%s  %-6s  %s  %s%s%s\n' \
        "$color" "$status" "$C_OFF" "$code" "$label" "$C_DIM" "$url" "$C_OFF"
    [[ ",$good," == *",$code,"* ]] || AYNEH_PROBE_FAILURES=$((AYNEH_PROBE_FAILURES + 1))
}

# Test whether a mirror actually serves packages (not just a landing page).
# Returns 0 (reachable & serving) or 1. The probe path depends on the kind of
# repository; several candidate paths are tried for layouts that vary between
# mirrors (notably yum and apk).
mirror_reachable() {
    local kind="$1" url="$2" svc="${3:-$1}" base="${2%/}" code
    case "$kind" in
        npm)
            code="$(http_code "${base}/npm")"
            [[ "$code" == "200" || "$code" == "301" || "$code" == "302" ]]
            ;;
        pypi)
            code="$(http_code "${base}/pip/")"
            [[ "$code" == "200" || "$code" == "301" || "$code" == "302" ]]
            ;;
        docker)
            code="$(http_code "${base}/v2/")"
            # Docker registry answers 401 on /v2/ — that means it is alive.
            [[ "$code" == "200" || "$code" == "401" ]]
            ;;
        apt)
            [[ -z "$DISTRO_CODENAME" ]] && return 1
            code="$(http_code "${base}/dists/${DISTRO_CODENAME}/Release")"
            [[ "$code" == "200" || "$code" == "301" || "$code" == "302" ]]
            ;;
        yum)
            # Mirror roots differ in their distro layout (e.g. /rocky vs
            # /rocky/9), and each RHEL flavor has its own tree. Probe the real
            # repodata path for the running release first, then fall back to
            # generic layouts.
            local major="${DISTRO_VERSION%%.*}"
            local -a cands=()
            case "$svc" in
                rocky)      cands=("${base}/${major}/BaseOS/${DISTRO_ARCH}/os/repodata/repomd.xml"
                                   "${base}/${DISTRO_VERSION}/BaseOS/${DISTRO_ARCH}/os/repodata/repomd.xml") ;;
                almalinux)  cands=("${base}/${major}/BaseOS/${DISTRO_ARCH}/os/repodata/repomd.xml"
                                   "${base}/${DISTRO_VERSION}/BaseOS/${DISTRO_ARCH}/os/repodata/repomd.xml") ;;
                centos)     cands=("${base}/${major}-stream/BaseOS/${DISTRO_ARCH}/os/repodata/repomd.xml"
                                   "${base}/${major}/BaseOS/${DISTRO_ARCH}/os/repodata/repomd.xml") ;;
                fedora)     cands=("${base}/releases/${DISTRO_VERSION}/Everything/${DISTRO_ARCH}/os/repodata/repomd.xml") ;;
                epel)       cands=("${base}/${major}/Everything/${DISTRO_ARCH}/repodata/repomd.xml"
                                   "${base}/${DISTRO_VERSION}/Everything/${DISTRO_ARCH}/repodata/repomd.xml") ;;
            esac
            cands+=("${base}/repodata/repomd.xml" "${base}/")
            for cand in "${cands[@]}"; do
                code="$(http_code "$cand")"
                case "$code" in
                    200|301|302) return 0 ;;
                    403) [[ "$cand" == "${base}/" ]] && return 0 ;;
                esac
            done
            return 1
            ;;
        pacman)
            code="$(http_code "${base}/core/os/${DISTRO_ARCH}/")"
            [[ "$code" == "200" || "$code" == "301" || "$code" == "302" ]]
            ;;
        apk)
            local branch cand
            branch="$(alpine_branch)"
            for cand in \
                "${base}/${branch}/main/${DISTRO_ARCH}/APKINDEX.tar.gz" \
                "${base}/${branch}/community/${DISTRO_ARCH}/APKINDEX.tar.gz" \
                "${base}/${DISTRO_ARCH}/APKINDEX.tar.gz"; do
                code="$(http_code "$cand")"
                [[ "$code" == "200" || "$code" == "301" || "$code" == "302" ]] && return 0
            done
            return 1
            ;;
        *)
            code="$(http_code "$base")"
            [[ "$code" == "200" || "$code" == "301" || "$code" == "302" ]]
            ;;
    esac
}

