# --- pacman: Arch / Arch-derivatives. Server root ($repo/os/$arch appended) ---
PACMAN_MIRRORS=(
    "ArvanCloud|https://mirror.arvancloud.ir/arch"
    "Isfahan UT|https://repo.iut.ac.ir/arch"
    "0-1.cloud|https://mirror.0-1.cloud/archlinux"
    "Freedif|https://mirror.freedif.org/archlinux"
    "MobinHost|https://mirror.mobinhost.com/archlinux"
)

# --- apk: Alpine. Root (<branch>/$repo/$arch appended) ---
APK_MIRRORS=(
    "0-1.cloud|https://mirror.0-1.cloud/alpine"
    "Freedif|https://mirror.freedif.org/alpine"
    "Isfahan UT|https://repo.iut.ac.ir/alpine"
    "Pardisco|https://mirrors.pardisco.co/alpine"
    "MobinHost|https://mirror.mobinhost.com/alpine"
    "ArvanCloud|https://mirror.arvancloud.ir/alpine"
)

# Registry accessor: print "Name|URL" lines for a service key.
get_mirrors() {
    case "$1" in
        npm)            printf '%s\n' "${NPM_MIRRORS[@]}" ;;
        pypi)           printf '%s\n' "${PYPI_MIRRORS[@]}" ;;
        docker)         printf '%s\n' "${DOCKER_MIRRORS[@]}" ;;
        ubuntu)         printf '%s\n' "${APT_UBUNTU_MIRRORS[@]}" ;;
        debian)         printf '%s\n' "${APT_DEBIAN_MIRRORS[@]}" ;;
        centos)         printf '%s\n' "${YUM_CENTOS_MIRRORS[@]}" ;;
        rocky)          printf '%s\n' "${YUM_ROCKY_MIRRORS[@]}" ;;
        almalinux|alma) printf '%s\n' "${YUM_ALMA_MIRRORS[@]}" ;;
        fedora)         printf '%s\n' "${YUM_FEDORA_MIRRORS[@]}" ;;
        epel)           printf '%s\n' "${YUM_EPEL_MIRRORS[@]}" ;;
        pacman)         printf '%s\n' "${PACMAN_MIRRORS[@]}" ;;
        apk)            printf '%s\n' "${APK_MIRRORS[@]}" ;;
        *) return 1 ;;
    esac
}

# Normalize friendly aliases to canonical registry keys.
#   apt  -> ubuntu/debian, depending on the running distro
#   yum  -> centos/rocky/almalinux/fedora, depending on the running distro
#   alma -> almalinux
# Prints an empty string when the alias cannot be resolved on this system.
resolve_service_key() {
    case "$1" in
        apt)
            if [[ "$DISTRO_ID" == "ubuntu" ]]; then echo "ubuntu"
            elif [[ "$DISTRO_FAMILY" == "debian" ]]; then echo "debian"
            else echo ""
            fi ;;
        yum|rhel) rhel_service_for_distro ;;
        alma) echo "almalinux" ;;
        *) echo "$1" ;;
    esac
}

# True when a service key (or alias) is known.
is_service() {
    local key s
    key="$(resolve_service_key "$1")"
    [[ -z "$key" ]] && return 1
    for s in "${AYNEH_SERVICES[@]}"; do
        [[ "$s" == "$key" ]] && return 0
    done
    return 1
}

# Map a service key to a human label.
service_label() {
    case "$1" in
        npm)    echo "npm registry" ;;
        pypi)   echo "Python PyPI / pip" ;;
        docker) echo "Docker registry" ;;
        ubuntu) echo "apt — Ubuntu" ;;
        debian) echo "apt — Debian" ;;
        centos) echo "dnf/yum — CentOS" ;;
        rocky)  echo "dnf/yum — Rocky Linux" ;;
        almalinux|alma) echo "dnf/yum — AlmaLinux" ;;
        fedora) echo "dnf/yum — Fedora" ;;
        epel)   echo "dnf/yum — EPEL" ;;
        pacman) echo "pacman — Arch" ;;
        apk)    echo "apk — Alpine" ;;
        *) echo "$1" ;;
    esac
}

# Map a service key to the reachability probe kind.
service_kind() {
    case "$1" in
        ubuntu|debian) echo "apt" ;;
        centos|rocky|almalinux|alma|fedora|epel) echo "yum" ;;
        *) echo "$1" ;;
    esac
}

# Pick the yum flavor that matches the running distro.
rhel_service_for_distro() {
    case "$DISTRO_ID" in
        rocky|rockylinux) echo "rocky" ;;
        almalinux|alma)   echo "almalinux" ;;
        fedora)           echo "fedora" ;;
        *)                echo "centos" ;;
    esac
}

# Resolve a mirror name to URL within a service (case-insensitive).
resolve_mirror() {
    local svc="$1" name="$2" line n u
    while IFS= read -r line; do
        [[ -z "$line" ]] && continue
        n="${line%%|*}"; u="${line#*|}"
        if [[ "${n,,}" == "${name,,}" ]]; then printf '%s\n' "$u"; return 0; fi
    done < <(get_mirrors "$svc")
    return 1
}

# ===== 40-scan.sh =====
# shellcheck shell=bash
# =============================================================================
# UPSTREAM SCANNERS — test the default upstream (and configured repos) for each
# service. These functions only read configuration; they never modify anything.
# =============================================================================

scan_npm() {
    hdr "npm registry"
    if ! has_npm; then warn "npm not installed — skipped."; return; fi
    local cur=""
    cur="$(npm config get registry 2>/dev/null || true)"
    info "current registry: ${cur:-unknown}"
    probe_url "npm upstream" "https://registry.npmjs.org/" 200
}

scan_pypi() {
    hdr "Python PyPI / pip"
    if ! has_pip; then warn "pip not installed — skipped."; return; fi
    local cur=""
    cur="$("$(pip_cmd)" config get global.index-url 2>/dev/null || true)"
    info "current index-url: ${cur:-default (https://pypi.org/simple)}"
    probe_url "PyPI upstream" "https://pypi.org/simple/" 200
}

scan_docker() {
    hdr "Docker registry"
    if ! has_docker; then warn "Docker not installed — skipped."; return; fi
    info "configured registry-mirrors:"
    if [[ -f /etc/docker/daemon.json ]]; then
        maybe_sudo grep -A5 registry-mirrors /etc/docker/daemon.json 2>/dev/null \
            | sed 's/^/    /' || info "    (none configured)"
    else
        info "    (no /etc/docker/daemon.json — using Docker Hub defaults)"
    fi
    # Docker registry answers 401 to anonymous /v2/ — that is "reachable".
    probe_url "Docker Hub upstream" "https://registry-1.docker.io/v2/" 401
}

# Return the configured apt source URIs (one per line, deduped).
# Handles classic .list (deb/deb-src lines) and deb822 .sources (URIs: lines).
_apt_uris() {
    {
        [[ -f /etc/apt/sources.list ]] && cat /etc/apt/sources.list 2>/dev/null
        for f in /etc/apt/sources.list.d/*.list; do
            [[ -e "$f" ]] && cat "$f" 2>/dev/null
        done
        for f in /etc/apt/sources.list.d/*.sources; do
            [[ -e "$f" ]] || continue
            awk '/^URIs:/{sub(/^URIs:[ \t]*/,""); gsub(/[ \t]+/,"\n"); print}' "$f" 2>/dev/null
        done
    } 2>/dev/null \
      | grep -oE 'https?://[^[:space:]"]+' | sed 's|/$||' | sort -u
}

# Print "uri|suite" pairs from apt sources (classic .list + deb822 .sources).
# Used for scanning the ACTUAL configured suite (e.g. trixie-security) rather
# than guessing from the codename — avoids false 404s on security repos.
_apt_sources() {
    local f
    {
        [[ -f /etc/apt/sources.list ]] && cat /etc/apt/sources.list 2>/dev/null
        for f in /etc/apt/sources.list.d/*.list; do [[ -e "$f" ]] && cat "$f" 2>/dev/null; done
    } 2>/dev/null | awk '
        /^[[:space:]]*(deb|deb-src)[[:space:]]/{
            sub(/^[[:space:]]*(deb|deb-src)[[:space:]]+/, "")
            while ($0 ~ /^\[/) sub(/^\[[^]]*\][[:space:]]*/, "")
            if ($1 != "" && $2 != "") print $1"|"$2
        }'
    for f in /etc/apt/sources.list.d/*.sources; do
        [[ -e "$f" ]] || continue
        awk '
            BEGIN{RS=""; FS="\n"}
            {
                uri=""; suite=""
                for (i=1; i<=NF; i++) {
                    if      ($i ~ /^URIs:/)   { sub(/^URIs:[ \t]*/,"",$i);   uri=$i }
                    else if ($i ~ /^Suites:/) { sub(/^Suites:[ \t]*/,"",$i); suite=$i }
                }
                if (uri != "" && suite != "") {
                    split(suite, S, /[ \t]+/); split(uri, U, /[ \t]+/)
                    for (k in U) if (U[k] != "") print U[k]"|"S[1]
                }
            }' "$f" 2>/dev/null
    done
}

scan_apt() {
    hdr "apt repositories ($DISTRO_ID)"
    if ! has_apt; then warn "apt not available — skipped."; return; fi
    local count=0 uri suite base
    while IFS='|' read -r uri suite; do
        [[ -z "$uri" || -z "$suite" ]] && continue
        count=$((count+1))
        base="${uri%/}"
        probe_url "apt $suite" "${base}/dists/${suite}/Release" 200
    done < <(_apt_sources | sort -u)
    [[ "$count" -eq 0 ]] && warn "No apt sources found."
}

# Return yum baseurls / metalinks (with $releasever/$basearch expanded).
_yum_repos() {
    local f
    for f in /etc/yum.repos.d/*.repo; do
        [[ -e "$f" ]] || continue
        awk -v rel="$DISTRO_VERSION" -v arch="$DISTRO_ARCH" '
            /^\[/{name=$0; next}
            /^[[:space:]]*baseurl[[:space:]]*=/{
                sub(/^[[:space:]]*baseurl[[:space:]]*=/,""); gsub(/\$releasever/, rel); gsub(/\$basearch/, arch); gsub(/\$arch/, arch);
                print "B|"name"|"$0
            }
            /^[[:space:]]*metalink[[:space:]]*=/{
                sub(/^[[:space:]]*metalink[[:space:]]*=/,""); gsub(/\$releasever/, rel); gsub(/\$basearch/, arch); gsub(/\$arch/, arch);
                print "M|"name"|"$0
            }
            /^[[:space:]]*mirrorlist[[:space:]]*=/{
                sub(/^[[:space:]]*mirrorlist[[:space:]]*=/,""); gsub(/\$releasever/, rel); gsub(/\$basearch/, arch); gsub(/\$arch/, arch);
                print "L|"name"|"$0
            }
        ' "$f" 2>/dev/null
    done
}

scan_yum() {
    hdr "dnf/yum repositories"
    if ! has_yum; then warn "dnf/yum not available — skipped."; return; fi
    local count=0 kind repoid url
    while IFS='|' read -r kind repoid url; do
        [[ -z "$url" ]] && continue
        count=$((count+1))
        case "$kind" in
            B) probe_url "baseurl $repoid" "${url%/}/repodata/repomd.xml" 200 ;;
            M|L) probe_url "metalink $repoid" "$url" 200,302,301 ;;
        esac
    done < <(_yum_repos)
    [[ "$count" -eq 0 ]] && warn "No yum/dnf repos found."
}

scan_pacman() {
    hdr "pacman mirrorlist"
    if ! has_pacman; then warn "pacman not available — skipped."; return; fi
    local first=""
    first="$(awk '/^[[:space:]]*Server[[:space:]]*=/{print $3; exit}' /etc/pacman.d/mirrorlist 2>/dev/null)"
    if [[ -z "$first" ]]; then
        warn "No Server entries in /etc/pacman.d/mirrorlist."
        return
    fi
    info "first mirror: $first"
    # Expand $repo/$arch to test with the core repo.
    local test_url="${first//\$repo/core}"
    test_url="${test_url//\$arch/$DISTRO_ARCH}"
    probe_url "pacman mirror" "$test_url" 200
}

scan_apk() {
    hdr "apk repositories"
    if ! has_apk; then warn "apk not available — skipped."; return; fi
    local count=0 line url test
    while IFS= read -r line; do
        line="${line%%#*}"
        # Trim surrounding whitespace.
        line="${line#"${line%%[![:space:]]*}"}"
        line="${line%"${line##*[![:space:]]}"}"
        [[ -z "$line" ]] && continue
        count=$((count+1))
        url="${line%/}"
        if [[ "$url" == http://* || "$url" == https://* ]]; then
            test="${url}/${DISTRO_ARCH}/APKINDEX.tar.gz"
            probe_url "apk repo #$count" "$test" 200
        else
            info "apk repo #$count: $url (local path — not probed)"
        fi
    done < /etc/apk/repositories 2>/dev/null
    [[ "$count" -eq 0 ]] && warn "No apk repositories configured."
}

# Run the scanner for a single service key (aliases like apt/yum allowed).
scan_service() {
    local key
    key="$(resolve_service_key "$1")"
    if [[ -z "$key" ]]; then
        err "Cannot map '$1' to a package family on this system."
        return 1
    fi
    case "$key" in
        npm)                scan_npm ;;
        pypi)               scan_pypi ;;
        docker)             scan_docker ;;
        ubuntu|debian)      scan_apt ;;
        centos|rocky|almalinux|alma|fedora|epel) scan_yum ;;
        pacman)             scan_pacman ;;
        apk)                scan_apk ;;
        *) err "Unknown service: $1"; return 1 ;;
    esac
}

scan_all() {
    require_curl
    AYNEH_PROBE_FAILURES=0
    hdr "System"
    os_summary
    scan_npm
    scan_pypi
    scan_docker
    if has_apt;    then scan_apt;    fi
    if has_yum;    then scan_yum;    fi
    if has_pacman; then scan_pacman; fi
    if has_apk;    then scan_apk;    fi
    echo
    if [[ "${AYNEH_PROBE_FAILURES:-0}" -eq 0 ]]; then
        ok "Scan complete. All probed endpoints responded."
    else
        warn "Scan complete. ${AYNEH_PROBE_FAILURES} endpoint(s) need attention — see the lines marked UNREACHABLE / HTTP 4xx/5xx."
        info "Run 'ayneh' → 3) Apply / switch a mirror to fix them."
    fi
}

# =============================================================================
# CURRENT CONFIG DISPLAY
# =============================================================================
show_config() {
    hdr "Current configuration"
    os_summary

    if has_npm; then
        printf '\n%s\n' "${C_BOLD}npm:${C_OFF}"
        printf '  registry: %s\n' "$(npm config get registry 2>/dev/null || echo '?')"
    fi
    if has_pip; then
        printf '\n%s\n' "${C_BOLD}pip:${C_OFF}"
        printf '  index-url: %s\n' "$("$(pip_cmd)" config get global.index-url 2>/dev/null || echo 'default (https://pypi.org/simple)')"
    fi
    if has_docker; then
        printf '\n%s\n' "${C_BOLD}docker:${C_OFF}"
        if [[ -f /etc/docker/daemon.json ]]; then
            printf '  daemon.json:\n'
            maybe_sudo sed 's/^/    /' /etc/docker/daemon.json 2>/dev/null
        else
            printf '  daemon.json: (none — Docker Hub defaults)\n'
        fi
    fi
    if has_apt; then
        printf '\n%s\n' "${C_BOLD}apt sources:${C_OFF}"
        _apt_uris | sed 's/^/  /'
    fi
    if has_yum; then
        printf '\n%s\n' "${C_BOLD}yum/dnf baseurls:${C_OFF}"
        _yum_repos | awk -F'|' '{print "  "$2"  "$3}'
    fi
    if has_pacman; then
        printf '\n%s\n' "${C_BOLD}pacman mirrors:${C_OFF}"
        awk '/^[[:space:]]*Server[[:space:]]*=/{print "  "$0}' /etc/pacman.d/mirrorlist 2>/dev/null | head -3
    fi
    if has_apk; then
        printf '\n%s\n' "${C_BOLD}apk repositories:${C_OFF}"
        sed 's/^/  /' /etc/apk/repositories 2>/dev/null
    fi
    echo
}

# ===== 50-backup.sh =====
# shellcheck shell=bash
# =============================================================================
# BACKUP / RESTORE
# -----------------------------------------------------------------------------
# Every file we are about to modify is copied to a timestamped .bak file, with
# a small .meta sidecar recording the original path. The sidecar makes restore
# reliable even when the original file has been moved or renamed.
# =============================================================================

# Print the directory that backs up a given source path.
_backup_dir_for() {
    local src="$1"
    if [[ "$src" == /etc/* || "$src" == /var/* ]]; then
        printf '%s\n' "$SYS_BACKUP_DIR"
    else
        printf '%s\n' "$USER_BACKUP_DIR"
    fi
}

# Write the .meta sidecar next to a backup (best effort).
_write_backup_meta() {
    local dest="$1" src="$2" tag="$3"
    local body
    body="$(printf 'source=%s\ntag=%s\ncreated=%s\n' "$src" "$tag" "$(date -u +%Y-%m-%dT%H:%M:%SZ)")"
    if [[ "$dest" == /var/* ]]; then
        printf '%s\n' "$body" | maybe_sudo tee "${dest}.meta" >/dev/null 2>&1 || true
    else
        printf '%s\n' "$body" > "${dest}.meta" 2>/dev/null || true
    fi
}

# Back up a file, print the backup path on success. $1=source $2=tag
backup_file() {
    local src="$1" tag="${2:-manual}"
    [[ ! -e "$src" ]] && return 1
    local stamp dest_dir dest base
    stamp="$(date +%Y%m%d-%H%M%S)"
    dest_dir="$(_backup_dir_for "$src")"
    base="${src##*/}"
    dest="${dest_dir}/${base}.${tag}.${stamp}.bak"

    if [[ "$dest_dir" == /var/* ]]; then
        maybe_sudo mkdir -p "$dest_dir" || return 1
        maybe_sudo cp -a "$src" "$dest" || return 1
    else
        mkdir -p "$dest_dir" || return 1
        cp -a "$src" "$dest" || return 1
    fi
    _write_backup_meta "$dest" "$src" "$tag"
    printf '%s\n' "$dest"
}

# Print all backup files, newest last, including legacy 1.x locations.
list_backups() {
    hdr "Available backups"
    local found=0 d f src
    for d in "$USER_BACKUP_DIR" "$LEGACY_USER_BACKUP_DIR" "$SYS_BACKUP_DIR" "$LEGACY_SYS_BACKUP_DIR"; do
        [[ -d "$d" ]] || continue
        while IFS= read -r f; do
            [[ -z "$f" ]] && continue
            src=""
            [[ -f "${f}.meta" ]] && src="$(sed -n 's/^source=//p' "${f}.meta" 2>/dev/null | head -1)"
            printf '  %s\n' "$f"
            [[ -n "$src" ]] && printf '      %s→ %s%s\n' "$C_DIM" "$src" "$C_OFF"
            found=$((found+1))
        done < <(find "$d" -maxdepth 1 -type f -name '*.bak' 2>/dev/null | sort)
    done
    if [[ "$found" -eq 0 ]]; then
        warn "No backups found yet."
        return 1
    fi
    return 0
}

# Restore a backup file to its original location. Reads the .meta sidecar when
# present and falls back to guessing from the filename for 1.x backups.
restore_backup() {
    local p="$1"
    [[ ! -f "$p" ]] && { err "File not found: $p"; return 1; }

    local target=""
    [[ -f "${p}.meta" ]] && target="$(sed -n 's/^source=//p' "${p}.meta" 2>/dev/null | head -1)"

    if [[ -z "$target" ]]; then
        local base; base="$(basename "$p")"
        local name
        name="$(printf '%s\n' "$base" | sed -E 's/\.[^.]+\.[^.]+\.bak$//')"
        local cand
        for cand in "/etc/$name" "/etc/docker/$name" "/etc/apt/$name" \
                    "/etc/apt/sources.list.d/$name" "/etc/yum.repos.d/$name" \
                    "/etc/pacman.d/$name" "$(real_home)/.$name" \
                    "$(real_home)/.config/pip/$name"; do
            if [[ -e "$cand" ]]; then target="$cand"; break; fi
        done
    fi

    if [[ -z "$target" ]]; then
        err "Could not infer the original location for '$(basename "$p")'."
        err "Please restore it manually from: $p"
        return 1
    fi
    if [[ ! -d "$(dirname "$target")" ]]; then
        err "Target directory does not exist: $(dirname "$target")"
        return 1
    fi

    if [[ "$target" == /etc/* || "$target" == /var/* ]]; then
        if ! ensure_sudo; then
            err "Restoring to $target needs root. Re-run:  sudo ayneh --restore \"$p\""
            return 1
        fi
        maybe_sudo cp -a "$p" "$target" || { err "Restore failed."; return 1; }
    else
        cp -a "$p" "$target" || { err "Restore failed."; return 1; }
    fi
    ok "Restored $target from $p"
}

# ===== 60-apply.sh =====
# shellcheck shell=bash
# =============================================================================
# MIRROR APPLIERS
# Each applier: verifies the mirror, backs up what it touches, applies the
# change, and tells the user how to refresh package indexes. Returns 0 on
# success, non-zero on any failure.
# =============================================================================

apply_npm() {
    local name="$1" url="$2"
    hdr "Applying npm mirror: $name"
    ensure_tmpdir
    if ! mirror_reachable npm "$url"; then
        err "Mirror is not serving npm packages — aborting (try another)."
        return 1
    fi
    ok "Mirror reachable."

    local npmrc; npmrc="$(real_home)/.npmrc"
    [[ -f "$npmrc" ]] && backup_file "$npmrc" npm >/dev/null && info "Backed up $npmrc"

    if running_as_root && [[ -n "${SUDO_USER:-}" ]]; then
        if has_npm; then
            sudo -u "$SUDO_USER" npm config set registry "$url" 2>/dev/null \
                || printf 'registry=%s\n' "$url" | sudo -u "$SUDO_USER" tee -a "$npmrc" >/dev/null
        else
            printf 'registry=%s\n' "$url" | sudo -u "$SUDO_USER" tee -a "$npmrc" >/dev/null
        fi
    else
        if has_npm; then
            npm config set registry "$url" 2>/dev/null \
                || { printf 'registry=%s\n' "$url" >> "$npmrc"; }
        else
            warn "npm not installed — writing $npmrc directly."
            printf 'registry=%s\n' "$url" >> "$npmrc"
        fi
    fi
    ok "npm registry set to: $url"
    info "Check with: npm config get registry"
}

apply_pypi() {
    local name="$1" url="$2"
    hdr "Applying PyPI mirror: $name"
    ensure_tmpdir
    if ! mirror_reachable pypi "$url"; then
        err "Mirror is not serving PyPI packages — aborting."
        return 1
    fi
    ok "Mirror reachable."

    local host="${url#*://}"; host="${host%%/*}"
    local conf_file conf_dir
    if running_as_root; then
        conf_file="/etc/pip.conf"
    else
        conf_dir="$(real_home)/.config/pip"; mkdir -p "$conf_dir"
        conf_file="$conf_dir/pip.conf"
    fi
    [[ -f "$conf_file" ]] && backup_file "$conf_file" pip >/dev/null && info "Backed up $conf_file"

    local newconf="$AYNEH_TMPDIR/pip.conf.new"
    {
        printf '[global]\n'
        printf 'index-url = %s\n' "$url"
        printf 'trusted-host = %s\n' "$host"
    } > "$newconf"

    if running_as_root; then maybe_sudo install -m 0644 "$newconf" "$conf_file" || return 1
    else cp "$newconf" "$conf_file" || return 1; fi
    ok "pip index-url set to: $url"
    [[ -n "$conf_file" ]] && info "Config file: $conf_file"
}

apply_docker() {
    local name="$1" url="$2"
    hdr "Applying Docker registry mirror: $name"
    ensure_tmpdir
    require_root docker "$name" || return 1
    if ! mirror_reachable docker "$url"; then
        err "Mirror is not responding as a Docker registry — aborting."
        return 1
    fi
    ok "Mirror reachable."

    local dj=/etc/docker/daemon.json
    local tmpjson="$AYNEH_TMPDIR/daemon.json"
    maybe_sudo mkdir -p /etc/docker || return 1
    [[ -f "$dj" ]] && backup_file "$dj" docker >/dev/null && info "Backed up $dj"

    if have python3; then
        if ! python3 - "$dj" "$url" "$tmpjson" <<'PY'
import json, os, sys

path, mirror, out = sys.argv[1], sys.argv[2], sys.argv[3]
data = {}
if os.path.exists(path) and os.path.getsize(path) > 0:
    try:
        with open(path) as f:
            data = json.load(f)
    except Exception as exc:  # keep going; the broken file has been backed up
        print("warning: existing daemon.json is not valid JSON: %s" % exc,
              file=sys.stderr)
        data = {}
mirrors = data.get("registry-mirrors", [])
if mirror in mirrors:
    mirrors.remove(mirror)
mirrors.insert(0, mirror)
seen, deduped = set(), []
for item in mirrors:
    if isinstance(item, str) and item not in seen:
        seen.add(item)
        deduped.append(item)
data["registry-mirrors"] = deduped
with open(out, "w") as f:
    json.dump(data, f, indent=2)
    f.write("\n")
PY
        then
            err "Could not merge daemon.json (python3 failed). Nothing changed."
            return 1
        fi
        maybe_sudo install -m 0644 "$tmpjson" "$dj" || return 1
    elif [[ ! -e "$dj" ]]; then
        printf '{\n  "registry-mirrors": ["%s"]\n}\n' "$url" | maybe_sudo tee "$dj" >/dev/null || return 1
    else
        err "python3 is required to safely merge an existing daemon.json."
        err "Install python3 and retry, or edit $dj manually."
        return 1
    fi

    ok "registry-mirrors now:"
    maybe_sudo sed 's/^/    /' "$dj"
    warn "Restart the Docker daemon to apply:"
    printf '    %s\n' "sudo systemctl restart docker   # or: sudo service docker restart"
}

# Generic apt host-swap for Ubuntu/Debian.
# $1=service (ubuntu|debian)  $2=mirror name  $3=mirror url
apply_apt() {
    local svc="$1" name="$2" url="$3"
    hdr "Applying apt mirror ($svc): $name"
    ensure_tmpdir
    require_root "$svc" "$name" || return 1
    if ! mirror_reachable apt "$url"; then
        err "Mirror is not serving the ${DISTRO_CODENAME:-configured} release — aborting."
        return 1
    fi
    ok "Mirror reachable for ${DISTRO_CODENAME:-this release}."

    # Host-swap per distro:
    #  - Ubuntu: any *ubuntu.com/ubuntu host/path → <mirror>
    #  - Debian: any *debian.org/debian host/path → <mirror>
    #    (this also rewrites /debian-security correctly, because only the
    #     substring ".../debian" is replaced and "-security" is kept)
    local sed_expr
    if [[ "$svc" == "ubuntu" ]]; then
        sed_expr="s|https?://[a-z0-9.-]*ubuntu\\.com/ubuntu|${url}|g"
    else
        sed_expr="s|https?://[a-z0-9.-]*debian\\.org/debian|${url}|g"
    fi

    local files=() f
    [[ -f /etc/apt/sources.list ]] && files+=(/etc/apt/sources.list)
    for f in /etc/apt/sources.list.d/*.list; do [[ -e "$f" ]] && files+=("$f"); done
    for f in /etc/apt/sources.list.d/*.sources; do [[ -e "$f" ]] && files+=("$f"); done
    if [[ "${#files[@]}" -eq 0 ]]; then
        warn "No apt sources files found to edit."
        return 1
    fi

    local tmpf before after changed=0
    for f in "${files[@]}"; do
        tmpf="$AYNEH_TMPDIR/$(basename "$f")"
        if ! maybe_sudo cat "$f" > "$tmpf" 2>/dev/null; then
            cat "$f" > "$tmpf" 2>/dev/null || continue
        fi
        before="$(cksum < "$tmpf")"
        sed -E -i "$sed_expr" "$tmpf"
        after="$(cksum < "$tmpf")"
        if [[ "$before" == "$after" ]]; then
            info "No upstream Ubuntu/Debian hosts in $f — left unchanged."
            continue
        fi
        backup_file "$f" apt >/dev/null && info "Backed up $f"
        if running_as_root; then
            maybe_sudo install -m 0644 "$tmpf" "$f" || return 1
        else
            maybe_sudo install -m 0644 "$tmpf" "$f" 2>/dev/null || cp "$tmpf" "$f" || return 1
        fi
        changed=$((changed+1))
    done
    if [[ "$changed" -eq 0 ]]; then
        warn "No apt sources were rewritten (no matching upstream hosts)."
        return 1
    fi
    ok "apt sources rewritten to: $url"
    warn "Refresh indexes:"
    printf '    %s\n' "sudo apt update"
}

apply_pacman() {
    local name="$1" url="$2"
    hdr "Applying pacman mirror: $name"
    ensure_tmpdir
    require_root pacman "$name" || return 1
    if ! mirror_reachable pacman "$url"; then
        err "Mirror is not serving Arch packages — aborting."
        return 1
    fi
    ok "Mirror reachable."

    local ml=/etc/pacman.d/mirrorlist
    local server="${url%/}/\$repo/os/\$arch"
    if grep -qF "Server = $server" "$ml" 2>/dev/null; then
        info "This mirror is already present in $ml."
    fi
    [[ -f "$ml" ]] && backup_file "$ml" pacman >/dev/null && info "Backed up $ml"

    local tmpf="$AYNEH_TMPDIR/mirrorlist"
    if ! maybe_sudo cat "$ml" > "$tmpf" 2>/dev/null; then
        cat "$ml" > "$tmpf" 2>/dev/null || return 1
    fi
    {
        printf '## Added by ayneh — %s — %s\n' "$name" "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
        printf 'Server = %s\n\n' "$server"
        cat "$tmpf"
    } > "$tmpf.new"

    if running_as_root; then
        maybe_sudo install -m 0644 "$tmpf.new" "$ml" || return 1
    else
        maybe_sudo install -m 0644 "$tmpf.new" "$ml" 2>/dev/null || cp "$tmpf.new" "$ml" || return 1
    fi
    ok "pacman mirror prepended: $url"
    warn "Refresh indexes:"
    printf '    %s\n' "sudo pacman -Syyu"
}

apply_apk() {
    local name="$1" url="$2"
    hdr "Applying apk mirror: $name"
    ensure_tmpdir
    require_root apk "$name" || return 1
    if ! mirror_reachable apk "$url"; then
        err "Mirror is not serving Alpine APKINDEX — aborting."
        return 1
    fi
    ok "Mirror reachable."

    local rep=/etc/apk/repositories
    [[ -f "$rep" ]] && backup_file "$rep" apk >/dev/null && info "Backed up $rep"
    local tmpf="$AYNEH_TMPDIR/repositories"
    if ! maybe_sudo cat "$rep" > "$tmpf" 2>/dev/null; then
        cat "$rep" > "$tmpf" 2>/dev/null || return 1
    fi
    local before after
    before="$(cksum < "$tmpf")"
    sed -E -i "s|https?://dl-cdn\.alpinelinux\.org/alpine|${url%/}|g" "$tmpf"
    after="$(cksum < "$tmpf")"
    if [[ "$before" == "$after" ]]; then
        warn "No dl-cdn.alpinelinux.org entries found in $rep — nothing changed."
        return 1
    fi
    if running_as_root; then
        maybe_sudo install -m 0644 "$tmpf" "$rep" || return 1
    else
        maybe_sudo install -m 0644 "$tmpf" "$rep" 2>/dev/null || cp "$tmpf" "$rep" || return 1
    fi
    ok "apk repositories rewritten to: $url"
    warn "Refresh indexes:"
    printf '    %s\n' "sudo apk update"
}

# Generic yum/dnf host-swap.
# $1=service (centos|rocky|almalinux|fedora|epel)  $2=name  $3=url
apply_yum() {
    local svc="$1" name="$2" url="$3"
    hdr "Applying dnf/yum mirror ($svc): $name"
    ensure_tmpdir
    require_root "$svc" "$name" || return 1
    if ! mirror_reachable yum "$url" "$svc"; then
        err "Mirror does not serve the ${DISTRO_ID} ${DISTRO_VERSION} repository tree — aborting."
        return 1
    fi
    ok "Mirror reachable for ${DISTRO_ID} ${DISTRO_VERSION}."

    local -A upstreams=(
        [centos]='mirror.stream.centos.org mirror.centos.org'
        [rocky]='dl.rockylinux.org'
        [almalinux]='repo.almalinux.org'
        [fedora]='download.fedoraproject.org dl.fedoraproject.org mirrors.fedoraproject.org'
        [epel]='download.fedoraproject.org dl.fedoraproject.org'
    )
    local ups="${upstreams[$svc]:-}"
    [[ -z "$ups" ]] && { err "Unknown yum service: $svc"; return 1; }

    # Build the replacement: upstream root → mirror root.
    # e.g. dl.rockylinux.org/pub/rocky/9/BaseOS/x86_64/os
    #   →  https://mirror.arvancloud.ir/rocky/9/BaseOS/x86_64/os
    local changed=0 f
    local tmpf before after u
    for f in /etc/yum.repos.d/*.repo; do
        [[ -e "$f" ]] || continue
        tmpf="$AYNEH_TMPDIR/$(basename "$f")"
        if ! maybe_sudo cat "$f" > "$tmpf" 2>/dev/null; then
            cat "$f" > "$tmpf" 2>/dev/null || continue
        fi
        before="$(cksum < "$tmpf")"
        # Uncomment a commented baseurl only when it points at a known upstream,
        # so a user's own commented-out private mirror is left alone.
        for u in $ups; do
            sed -E -i "s|^([[:space:]]*)#+[[:space:]]*(baseurl=https?://${u})|\1\2|" "$tmpf"
        done
        for u in $ups; do
            case "$svc:$u" in
                centos:*)    sed -E -i "s|https?://${u}/centos|${url}|g; s|https?://${u}|${url}|g" "$tmpf" ;;
                rocky:*)     sed -E -i "s|https?://${u}/pub/rocky|${url}|g" "$tmpf" ;;
                almalinux:*) sed -E -i "s|https?://${u}/pub/almalinux|${url}|g; s|https?://${u}/almalinux|${url}|g" "$tmpf" ;;
                fedora:*)    sed -E -i "s#https?://${u}/pub/fedora/linux#${url%/}#g; s#https?://${u}/pub/fedora#${url%/}#g" "$tmpf" ;;
                epel:*)      sed -E -i "s#https?://${u}/pub/epel#${url%/}#g" "$tmpf" ;;
            esac
        done
        # Count sections and sections that have an ACTIVE baseurl. Metalink /
        # mirrorlist may only be commented out when every section has a baseurl,
        # otherwise dnf would be left with no URL at all.
        local counts sec_total sec_base
        counts="$(awk '
            /^\[/ { if (in_sec) { total++; if (has_base) with_base++ } in_sec=1; has_base=0; next }
            /^[[:space:]]*baseurl[[:space:]]*=/ { has_base=1 }
            END { if (in_sec) { total++; if (has_base) with_base++ } ; print total+0, with_base+0 }
        ' "$tmpf")"
        sec_total="${counts%% *}"; sec_base="${counts##* }"
        if [[ "$sec_total" -gt 0 && "$sec_total" == "$sec_base" ]]; then
            # Comment out metalink/mirrorlist so baseurl takes effect.
            sed -E -i 's|^([[:space:]]*)(metalink=)|\1#\2|g; s|^([[:space:]]*)(mirrorlist=)|\1#\2|g' "$tmpf"
        else
            warn "Some sections in $(basename "$f") use mirrorlist without a baseurl; left them enabled."
        fi
        after="$(cksum < "$tmpf")"
        [[ "$before" == "$after" ]] && continue
        backup_file "$f" yum >/dev/null && info "Backed up $f"
        if running_as_root; then
            maybe_sudo install -m 0644 "$tmpf" "$f" || return 1
        else
            maybe_sudo install -m 0644 "$tmpf" "$f" 2>/dev/null || cp "$tmpf" "$f" || return 1
        fi
        changed=$((changed+1))
    done
    if [[ "$changed" -eq 0 ]]; then
        warn "No repo files matched this upstream — nothing changed."
        return 1
    fi
    ok "Repo files rewritten (host-swap to: $url)."
    warn "Refresh indexes:"
    printf '    %s\n' "sudo $PKGMGR makecache   # or: sudo $PKGMGR check-update"
}

# Dispatcher: apply a mirror for any service.
apply_mirror() {
    require_curl
    local svc="$1" name="$2" url="$3"
    case "$svc" in
        npm)    apply_npm    "$name" "$url" ;;
        pypi)   apply_pypi   "$name" "$url" ;;
        docker) apply_docker "$name" "$url" ;;
        ubuntu|debian) apply_apt "$svc" "$name" "$url" ;;
        centos|rocky|almalinux|alma|fedora|epel) apply_yum "$svc" "$name" "$url" ;;
        pacman) apply_pacman "$name" "$url" ;;
        apk)    apply_apk    "$name" "$url" ;;
        *) err "Unknown service: $svc"; return 1 ;;
    esac
}

# ===== 70-menu.sh =====
# shellcheck shell=bash
# =============================================================================
# INTERACTIVE MENU — list mirrors for a service, test each, let the user pick.
# =============================================================================
menu_pick_mirror() {
    require_curl
    local svc="$1"
    hdr "Iranian mirrors — $(service_label "$svc")"
    local kind; kind="$(service_kind "$svc")"
    local entries=() names=() urls=() line name url i=0
    while IFS= read -r line; do
        [[ -z "$line" ]] && continue
        name="${line%%|*}"; url="${line#*|}"
        entries+=("$line"); names+=("$name"); urls+=("$url")
    done < <(get_mirrors "$svc")
    if [[ "${#entries[@]}" -eq 0 ]]; then warn "No mirrors registered for '$svc'."; return 1; fi

    # Probe all mirrors in PARALLEL. Down mirrors can take up to AYNEH_MAX_TIME
    # each, so sequential probing of 15-20 mirrors would be painfully slow;
    # running them concurrently caps total time at roughly the slowest probe.
    ensure_tmpdir
    info "Testing ${#entries[@]} mirrors in parallel (this takes ~${AYNEH_MAX_TIME}s)..."
    local results="$AYNEH_TMPDIR/picker.$$"
    : > "$results"
    for ((i=0; i<${#entries[@]}; i++)); do
        (
            if mirror_reachable "$kind" "${urls[$i]}" "$svc"; then
                printf '%s|1\n' "$i" >> "$results"
            else
                printf '%s|0\n' "$i" >> "$results"
            fi
        ) &
    done
    wait

    # Collect statuses (default "0" for any that failed to write).
    local -a statuses=()
    for ((i=0; i<${#entries[@]}; i++)); do statuses[i]="0"; done
    local idx st
    while IFS='|' read -r idx st; do
        [[ -z "$idx" ]] && continue
        statuses[idx]="$st"
    done < "$results"
    rm -f "$results"

    # Render the table.
    printf '  %s%-3s %-22s %-10s %s%s\n' "$C_BOLD" "#" "MIRROR" "STATUS" "URL" "$C_OFF"
    printf '  %s\n' "------------------------------------------------------------"
    local color
    for ((i=0; i<${#entries[@]}; i++)); do
        if [[ "${statuses[$i]}" == "1" ]]; then st="OK"; color="$C_GREEN"
        else st="down"; color="$C_RED"; fi
        printf '  %s%-3s%s %-22s %s%-8s%s %s\n' \
            "$C_BOLD" "$((i+1))" "$C_OFF" "${names[$i]}" "$color" "$st" "$C_OFF" "${urls[$i]}"
    done
    echo
    info "Type a number to apply that mirror, or 0 to go back."
    local choice
    ask choice "Apply mirror #> " || { echo; return 0; }
    [[ "$choice" == "0" || -z "$choice" ]] && return 0
    if ! [[ "$choice" =~ ^[0-9]+$ ]] || (( choice < 1 || choice > ${#entries[@]} )); then
        err "Invalid choice."; return 1
    fi
    idx=$((choice-1))
    if [[ "${statuses[$idx]}" != "1" ]]; then
        warn "That mirror was unreachable in the test. Apply anyway?"
        confirm "  proceed" n || return 1
    fi
    apply_mirror "$svc" "${names[$idx]}" "${urls[$idx]}"
}

# Top-level services menu
menu_services() {
    while true; do
        hdr "Choose a service"
        cat <<EOF
  ${C_BOLD}1)${C_OFF} npm registry         $(has_npm && echo "${C_GREEN}available${C_OFF}" || echo "${C_DIM}not installed${C_OFF}")
  ${C_BOLD}2)${C_OFF} Python PyPI / pip    $(has_pip && echo "${C_GREEN}available${C_OFF}" || echo "${C_DIM}not installed${C_OFF}")
  ${C_BOLD}3)${C_OFF} Docker registry      $(has_docker && echo "${C_GREEN}available${C_OFF}" || echo "${C_DIM}not installed${C_OFF}")
  ${C_BOLD}4)${C_OFF} apt — Ubuntu         $([ "$DISTRO_ID" == ubuntu ] && echo "${C_GREEN}$DISTRO_CODENAME${C_OFF}" || echo "${C_DIM}n/a${C_OFF}")
  ${C_BOLD}5)${C_OFF} apt — Debian         $([ "$DISTRO_FAMILY" == debian ] && [ "$DISTRO_ID" != ubuntu ] && echo "${C_GREEN}$DISTRO_CODENAME${C_OFF}" || echo "${C_DIM}n/a${C_OFF}")
  ${C_BOLD}6)${C_OFF} dnf/yum — CentOS/Rocky/Alma/Fedora
  ${C_BOLD}7)${C_OFF} dnf/yum — EPEL
  ${C_BOLD}8)${C_OFF} pacman — Arch
  ${C_BOLD}9)${C_OFF} apk — Alpine
  ${C_BOLD}0)${C_OFF} back
EOF
        local c
        ask c "> " || { echo; return 0; }
        case "$c" in
            1) menu_pick_mirror npm ;;
            2) menu_pick_mirror pypi ;;
            3) menu_pick_mirror docker ;;
            4) menu_pick_mirror ubuntu ;;
            5) menu_pick_mirror debian ;;
            6) menu_pick_mirror "$(rhel_service_for_distro)" ;;
            7) menu_pick_mirror epel ;;
            8) menu_pick_mirror pacman ;;
            9) menu_pick_mirror apk ;;
            0|"") return 0 ;;
            *) warn "Invalid choice." ;;
        esac
    done
}

# Test an arbitrary mirror URL
menu_test_mirror() {
    require_curl
    hdr "Test any mirror URL"
    local u
    ask u "URL> " || { echo; return 0; }
    [[ -z "$u" ]] && return 0
    local code; code="$(http_code "$u")"
    local status color
    if [[ "$code" == "200" ]]; then status="OK"; color="$C_GREEN"
    elif [[ "$code" == "000" ]]; then status="UNREACHABLE"; color="$C_RED"
    else status="HTTP $code"; color="$C_YELLOW"; fi
    printf '  %s%s%s  %s\n' "$color" "$status" "$C_OFF" "$u"
}

menu_list_mirrors() {
    hdr "All registered Iranian mirrors"
    local s
    for s in "${AYNEH_SERVICES[@]}"; do
        printf '\n%s%s%s\n' "$C_BOLD" "$(service_label "$s")" "$C_OFF"
        get_mirrors "$s" | awk -F'|' '{printf "  %-22s %s\n", $1, $2}'
    done
}

menu_restore() {
    list_backups || { pause; return 0; }
    hdr "Restore a backup"
    info "Enter the full path shown above (or blank to cancel)."
    local p
    ask p "path> " || { echo; return 0; }
    [[ -z "$p" ]] && return 0
    warn "This will overwrite the original location recorded for that backup."
    confirm "  restore" n || return 1
    restore_backup "$p"
}

banner() {
    printf '\n%s' "$C_BOLD$C_CYAN"
    cat <<'EOF'
    _
   / \  _   _ _ __   ___| |__
  / _ \| | | | '_ \ / _ \ '_ \
 / ___ \ |_| | | | |  __/ | | |
/_/   \_\__, |_| |_|\___|_| |_|
        |___/
EOF
    printf '%s\n' "$C_OFF"
    printf '%s\n' "${C_DIM}Iranian repository mirror scanner & configurator  v${AYNEH_VERSION}${C_OFF}"
    printf '%s\n' "${C_DIM}------------------------------------------------------------${C_OFF}"
    os_summary
    printf '%s\n' "${C_DIM}------------------------------------------------------------${C_OFF}"
}

menu_main() {
    while true; do
        cat <<EOF

  ${C_BOLD}1)${C_OFF} Scan all repositories now
  ${C_BOLD}2)${C_OFF} Scan a single service
  ${C_BOLD}3)${C_OFF} Apply / switch a mirror  ${C_YELLOW}(interactive)${C_OFF}
  ${C_BOLD}4)${C_OFF} Show current configuration
  ${C_BOLD}5)${C_OFF} List all known Iranian mirrors
  ${C_BOLD}6)${C_OFF} Test any mirror URL
  ${C_BOLD}7)${C_OFF} Restore from backup
  ${C_BOLD}0)${C_OFF} Exit

EOF
        local c
        ask c "${C_BOLD}ayneh>${C_OFF} " || { echo "Bye."; return 0; }
        case "$c" in
            1) scan_all; pause ;;
            2)
                hdr "Scan a single service"
                cat <<EOF
  1) npm   2) PyPI   3) Docker   4) apt   5) yum/dnf   6) pacman   7) apk   0) back
EOF
                local s; ask s "> "
                case "$s" in
                    1) scan_service npm ;;
                    2) scan_service pypi ;;
                    3) scan_service docker ;;
                    4) scan_service apt ;;
                    5) scan_service yum ;;
                    6) scan_service pacman ;;
                    7) scan_service apk ;;
                    0|"") ;;
                    *) warn "Invalid." ;;
                esac
                pause ;;
            3) menu_services; pause ;;
            4) show_config; pause ;;
            5) menu_list_mirrors; pause ;;
            6) menu_test_mirror; pause ;;
            7) menu_restore; pause ;;
            0|q|exit) echo "Bye."; return 0 ;;
            "") ;;
            *) warn "Invalid choice." ;;
        esac
    done
}

# ===== 90-main.sh =====
# shellcheck shell=bash
# =============================================================================
# CLI (non-interactive) interface and program entry point
# =============================================================================
usage() {
    cat <<EOF
${C_BOLD}ayneh${C_OFF} v${AYNEH_VERSION} — Iranian repository mirror scanner & configurator

${C_BOLD}Usage:${C_OFF}
  ayneh                        Interactive menu
  ayneh --scan [service]       Scan all repositories (or one service) and report
  ayneh --show                 Show current configuration
  ayneh --list [service]       List mirrors (all, or one service)
  ayneh --test <url>           Test reachability of any URL
  ayneh --apply <svc> <name>   Apply a mirror by service + name
                               (e.g. --apply npm Liara)
  ayneh --apply <svc> --url <u>  Apply a mirror by raw URL
  ayneh --restore [path]       List backups, or restore one
  ayneh --version              Print version
  ayneh --help                 This help

${C_BOLD}Services:${C_OFF} npm, pypi, docker, ubuntu, debian, centos, rocky,
            almalinux, fedora, epel, pacman, apk
            (aliases: apt = ubuntu/debian, yum = rhel flavor, alma = almalinux)

${C_BOLD}One-line run (no install):${C_OFF}
  curl -fsSL https://raw.githubusercontent.com/${AYNEH_REPO}/${AYNEH_BRANCH}/dist/ayneh.sh | bash
  curl -fsSL https://raw.githubusercontent.com/${AYNEH_REPO}/${AYNEH_BRANCH}/dist/ayneh.sh | bash -s -- --scan

${C_BOLD}Install as a command:${C_OFF}
  curl -fsSL https://raw.githubusercontent.com/${AYNEH_REPO}/${AYNEH_BRANCH}/install.sh | sudo bash
  ayneh

${C_BOLD}Environment:${C_OFF}
  NO_COLOR=1              Disable colors
  AYNEH_CONNECT_TIMEOUT   curl connect timeout in seconds (default ${AYNEH_CONNECT_TIMEOUT})
  AYNEH_MAX_TIME          curl total timeout in seconds (default ${AYNEH_MAX_TIME})
EOF
}

# Print the URL for a mirror name, or fail.
# Resolve a known service + custom URL / name into MIRROR_NAME/MIRROR_URL.
_parse_apply_target() {
    local svc="$1"; shift
    local name="${1:-}" url=""
    if [[ "$name" == "--url" || "$name" == "-u" ]]; then
        shift
        url="${1:-}"
        name="custom"
    elif [[ -n "$name" ]]; then
        url="$(resolve_mirror "$svc" "$name" || true)"
    fi
    if [[ -z "$url" ]]; then
        err "Mirror not found for service '$svc'."
        err "Use: ayneh --apply <service> <name>   or   ayneh --apply <service> --url <url>"
        err "Known names for '$svc':"
        get_mirrors "$svc" 2>/dev/null | awk -F'|' '{printf "    %-22s %s\n",$1,$2}' >&2
        return 1
    fi
    if [[ ! "$url" =~ ^https?:// ]]; then
        err "Not an http(s) URL: $url"
        return 1
    fi
    printf '%s\n%s\n' "$name" "$url"
}

parse_args() {
    while [[ $# -gt 0 ]]; do
        case "$1" in
            -h|--help)    usage; exit 0 ;;
            -v|--version) printf '%s v%s\n' "$PROG" "$AYNEH_VERSION"; exit 0 ;;
            --scan|-s)
                shift
                local scan_svc=""
                if [[ $# -gt 0 && "$1" != -* ]]; then
                    if ! is_service "$1"; then
                        err "Unknown service: $1"
                        err "Valid services: ${AYNEH_SERVICES[*]}"
                        exit 1
                    fi
                    scan_svc="$1"; shift
                fi
                if [[ -n "$scan_svc" ]]; then scan_service "$scan_svc"; else scan_all; fi
                exit 0 ;;
            --show)       show_config; exit 0 ;;
            --list|-l)
                shift
                if [[ $# -gt 0 && "$1" != -* ]]; then
                    if ! is_service "$1"; then
                        err "Unknown service: $1"
                        err "Valid services: ${AYNEH_SERVICES[*]}"
                        exit 1
                    fi
                    get_mirrors "$(resolve_service_key "$1")" | awk -F'|' '{printf "%-22s %s\n",$1,$2}'
                    shift
                else
                    menu_list_mirrors
                fi
                exit 0 ;;
            --test|-t)
                shift
                if [[ -z "${1:-}" ]]; then err "URL required. See --help."; exit 1; fi
                code="$(http_code "$1")"
                printf '%s  %s\n' "$code" "$1"
                exit 0 ;;
            --apply|-a)
                shift
                local svc="${1:-}"
                if [[ -z "$svc" ]]; then err "Service required. See --help."; exit 1; fi
                if ! is_service "$svc"; then err "Unknown service: $svc"; exit 1; fi
                svc="$(resolve_service_key "$svc")"
                shift
                local parsed name url
                if ! parsed="$(_parse_apply_target "$svc" "$@")"; then exit 1; fi
                name="$(printf '%s\n' "$parsed" | sed -n '1p')"
                url="$(printf '%s\n' "$parsed" | sed -n '2p')"
                apply_mirror "$svc" "$name" "$url"
                exit $? ;;
            --restore)
                shift
                if [[ -n "${1:-}" ]]; then
                    restore_backup "$1"; exit $?
                else
                    list_backups || true
                    echo
                    info "To restore one: ayneh --restore <path>   (or use the menu)"
                    exit 0
                fi ;;
            --interactive) return 0 ;;
            *) err "Unknown option: $1"; usage; exit 1 ;;
        esac
    done
}

main() {
    detect_os
    if [[ $# -gt 0 ]]; then
        parse_args "$@"
    fi
    require_curl
    ensure_tmpdir
    banner
    menu_main
}

# ===== entrypoint =====
if [[ "${AYNEH_LIB_ONLY:-0}" != "1" ]]; then
    main "$@"
fi
